import { BASE } from './site';

/**
 * Responsive WebP sources for a photo in public/.
 * The variants are generated by scripts/optimise-images.py as
 * `<name>-<width>.webp` next to the original file.
 *
 * @param {string} src    path of the original, e.g. '/images/speakers/adam-cox.jpg'
 * @param {number[]} widths  generated widths, smallest first
 * @returns {{ src: string, srcSet: string }}
 */
export function webpSources(src, widths) {
  const stem = src.replace(/\.(jpe?g|png)$/i, '');
  const url = width => `${BASE}${stem}-${width}.webp`;
  return {
    src: url(widths[widths.length - 1]),
    srcSet: widths.map(width => `${url(width)} ${width}w`).join(', '),
  };
}

export const SPEAKER_WIDTHS = [240, 480];
export const PHOTO_WIDTHS = [700, 1400];
export const HERO_WIDTHS = [800, 1600];
export const LOGO_SRC = `${BASE}/logo-160.webp`;
